        if ((codepoint <= 127)) {
            if (((codepoint >= 65) and (codepoint <= 90))) {
                return .{ .codepoints = .{ (codepoint + (97 - 65)), 0, 0 }, .n_codepoints = 1 };
            }
            return .{ .codepoints = .{ codepoint, 0, 0 }, .n_codepoints = 1 };
        }
        return ((caseFoldFromMap(1, (&fold_map_1), (&fold_map_1_data), codepoint)) orelse (((caseFoldFromMap(2, (&fold_map_2), (&fold_map_2_data), codepoint)) orelse (((caseFoldFromMap(3, (&fold_map_3), (&fold_map_3_data), codepoint)) orelse (FoldInfo{ .codepoints = .{ codepoint, 0, 0 }, .n_codepoints = 1 }))))));
}

pub fn caseFoldFromMap(comptime n: u2, map: []const u32, data: []const u21, codepoint: u21) ?FoldInfo {
        const index = ((unicodeBsearch(codepoint, map)) orelse { return null; });
        const data_offset = (index * (if (comptime @typeInfo(@TypeOf(n)) == .@"enum") cp_cast_int(usize, @intFromEnum(n)) else cp_cast_int(usize, n)));
        var result = FoldInfo{ .codepoints = .{ 0, 0, 0 }, .n_codepoints = n };
        _ = &result;
        inline for (0..n) |k| {
            result.codepoints[cp_cast_int(usize, k)] = data[@as(usize, @intCast((data_offset + k)))];
        }
        const map_cp = rawCodepoint(map[@as(usize, @intCast(index))]);
        if ((map_cp != codepoint)) {
            if (((map_cp + 1) == result.codepoints[0])) {
                result.codepoints[cp_cast_int(usize, 0)] = (codepoint + (if (((codepoint & 1) == (map_cp & 1))) (if (comptime @typeInfo(u21) == .@"enum") @as(u21, @enumFromInt(1)) else @as(u21, 1)) else (if (comptime @typeInfo(u21) == .@"enum") @as(u21, @enumFromInt(0)) else @as(u21, 0))));
            } else {
                result.codepoints[cp_cast_int(usize, 0)] = (result.codepoints[0] + (codepoint - map_cp));
            }
        }
        return result;
}

pub fn test_unicode_1() !void {
        const info_A = caseFold(65);
        _ = try std.testing.expectEqual((if (comptime @typeInfo(u21) == .@"enum") @as(u21, @enumFromInt(97)) else @as(u21, 97)), info_A.codepoints[0]);
        _ = try std.testing.expectEqual((if (comptime @typeInfo(u2) == .@"enum") @as(u2, @enumFromInt(1)) else @as(u2, 1)), info_A.n_codepoints);
        const info_Z = caseFold(90);
        _ = try std.testing.expectEqual((if (comptime @typeInfo(u21) == .@"enum") @as(u21, @enumFromInt(122)) else @as(u21, 122)), info_Z.codepoints[0]);
        _ = try std.testing.expectEqual((if (comptime @typeInfo(u2) == .@"enum") @as(u2, @enumFromInt(1)) else @as(u2, 1)), info_Z.n_codepoints);
        const info_a = caseFold(97);
        _ = try std.testing.expectEqual((if (comptime @typeInfo(u21) == .@"enum") @as(u21, @enumFromInt(97)) else @as(u21, 97)), info_a.codepoints[0]);
        _ = try std.testing.expectEqual((if (comptime @typeInfo(u2) == .@"enum") @as(u2, @enumFromInt(1)) else @as(u2, 1)), info_a.n_codepoints);
        const info_0 = caseFold(48);
        _ = try std.testing.expectEqual((if (comptime @typeInfo(u21) == .@"enum") @as(u21, @enumFromInt(48)) else @as(u21, 48)), info_0.codepoints[0]);
        _ = try std.testing.expectEqual((if (comptime @typeInfo(u2) == .@"enum") @as(u2, @enumFromInt(1)) else @as(u2, 1)), info_0.n_codepoints);
}

